/* University art-local observation view. EXAMINE never opens the closed gates. */
import {project} from './city-core.mjs?v=p21-b407-s039-reuse';import {universityViewContract} from './city-art.mjs?v=p21-b407-s039-reuse';
export async function createUniversityView({dialog,canvas,load,read,recruit,characterPainter,close}){
 const path='assets/city-v010/university/',m=await read(path+'placement.json'),contract=universityViewContract(m),placements=contract.placements,ctx=canvas.getContext('2d');
 const objects=await Promise.all(placements.map(async p=>({...p,im:await load(path+p.file.split('/').pop())}))),ground=await load(path+'uu_courtyard_patch.webp');
 // The real city player remains at the public EXAMINE approach. This view uses
 // its closed-gate art-local reference only; camera inspection adds no walk state.
 const player=[15,27],p0=project(player);let zoom=.9,cam={x:p0.x,y:p0.y-90},focus='gatehouse',drag=null,frameCost=0,paintCount=0,raf=0;
 const names={gatehouse:'Closed Great Gates',library:'Library',great_hall:'Great Hall',hem:'High Energy Magic',tower_of_art:'Tower of Art',whole:'University grounds'};
 const cameraTo=id=>{focus=id;if(id==='whole'){const bounds=objects.map(o=>{const q=project(o.anchor_local_uv);return[q.x-o.anchor_px[0]*o.render_scale,q.y-o.anchor_px[1]*o.render_scale,o.im.width*o.render_scale,o.im.height*o.render_scale];}),xs=bounds.flatMap(b=>[b[0],b[0]+b[2]]),ys=bounds.flatMap(b=>[b[1],b[1]+b[3]]),r=canvas.getBoundingClientRect();zoom=Math.min(.55,(r.width-26)/(Math.max(...xs)-Math.min(...xs)),(r.height-40)/(Math.max(...ys)-Math.min(...ys)));cam={x:(Math.min(...xs)+Math.max(...xs))/2,y:(Math.min(...ys)+Math.max(...ys))/2};}else{const o=objects.find(o=>o.id===id),q=project(id==='gatehouse'?player:o.visual_approach_local_uv||o.anchor_local_uv);zoom=.9;cam={x:q.x,y:q.y-(id==='tower_of_art'?500:90)};}$('university-location').textContent=names[id]||'University grounds';$('university-hint').textContent=id==='gatehouse'?'The gates are closed. Drag to look around or choose a building.':'Looking across the grounds. Return to Gates to see your approach.';draw();};
 const $=id=>dialog.querySelector('#'+id);
 function draw(){if(!dialog.open)return;const start=performance.now(),r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);}ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle='#6a6556';ctx.fillRect(0,0,r.width,r.height);ctx.save();ctx.translate(r.width/2,r.height/2);ctx.scale(zoom,zoom);ctx.translate(-cam.x,-cam.y);
 ctx.save();ctx.beginPath();[[0,0],[26,0],[26,26],[0,26]].map(p=>project(p)).forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.clip();for(const u of [16,32])for(const v of [16,32]){const q=project([u,v]);ctx.drawImage(ground,q.x-456,q.y-456);}ctx.restore();
 const sorted=objects.slice().sort((a,b)=>{const A=a.footprint_local_xywh,B=b.footprint_local_xywh;return A.reduce((x,y)=>x+y)-B.reduce((x,y)=>x+y);});
 const inFront=o=>{const [x,y,w,h]=o.footprint_local_xywh;return player[0]>x+w-.5||player[1]>y+h-.5;};
 const paint=o=>{const q=project(o.anchor_local_uv),s=o.render_scale;ctx.drawImage(o.im,q.x-o.anchor_px[0]*s,q.y-o.anchor_px[1]*s,o.im.width*s,o.im.height*s);};
 // Player is outside every body at the closed gate. Preserve whole layers, no
 // character slicing or hidden passage. Panning changes only the camera.
 for(const o of sorted.filter(inFront))paint(o);
 const C=window.CWCharacters,a=characterPainter.playerMeta,h=C.height(a,characterPainter.playerKey);ctx.fillStyle='#1a21186b';ctx.beginPath();ctx.ellipse(p0.x,p0.y,Math.max(5,h*.19),Math.max(2,h*.06),0,0,Math.PI*2);ctx.fill();C.draw(ctx,a,{actorId:'player',clip:'idle',facing:-1,reduced:true},p0.x,p0.y,h);
 for(const o of sorted.filter(o=>!inFront(o)))paint(o);
 ctx.strokeStyle='#edcc7e';ctx.lineWidth=1.4;ctx.beginPath();ctx.ellipse(p0.x,p0.y,13,5,0,0,Math.PI*2);ctx.stroke();ctx.restore();frameCost=performance.now()-start;paintCount++;canvas.dataset.ready='true';canvas.dataset.focus=focus;canvas.dataset.zoom=zoom.toFixed(4);canvas.dataset.actorHeight=String(h);canvas.dataset.character=characterPainter.playerKey;canvas.dataset.doorHeight='65';canvas.dataset.navAdded='false';canvas.dataset.gate='closed';canvas.dataset.frameCost=frameCost.toFixed(2);}
 dialog.querySelectorAll('[data-university-camera]').forEach(b=>b.onclick=()=>cameraTo(b.dataset.universityCamera));$('university-return').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{cancelAnimationFrame(raf);close();});
 canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,cx:cam.x,cy:cam.y};canvas.focus();});canvas.addEventListener('pointermove',e=>{if(!drag)return;cam={x:drag.cx-(e.clientX-drag.x)/zoom,y:drag.cy-(e.clientY-drag.y)/zoom};draw();});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);
 canvas.addEventListener('keydown',e=>{const d={ArrowLeft:[-80,0],ArrowRight:[80,0],ArrowUp:[0,-80],ArrowDown:[0,80]}[e.key];if(d){e.preventDefault();cam.x+=d[0]/zoom;cam.y+=d[1]/zoom;draw();}});new ResizeObserver(()=>{if(dialog.open){if(focus==='whole')cameraTo('whole');else draw();}}).observe(canvas);
 return {open(){dialog.showModal();raf=requestAnimationFrame(()=>cameraTo('gatehouse'));},report:()=>({open:dialog.open,focus,zoom,gateOpen:false,navAdded:false,cityApproach:contract.approach,cityPlot:contract.cityPlot,doorHeight:65,actorHeight:window.CWCharacters.height(characterPainter.playerMeta,characterPainter.playerKey),character:characterPainter.playerKey,paintCount,frameCost,placements:objects.length})};
}
